"use client";

import React, { useState, useEffect } from 'react';
import Link from 'next/link';
import Image from 'next/image';
import { ArrowRight } from 'lucide-react';

export default function Hero() {
  const [currentSlide, setCurrentSlide] = useState(0);

  // New slides: Disability students in university settings + your exact palette
  const slides = [
    {
    image: "/images/banner3.avif", // University student in wheelchair in lecture hall
      title: "WE ARE REGISTERED NDIS PROVIDER",
      subtitle: "DISABILITY SUPPORT",
      highlight: "FOR UNIVERSITY STUDENTS",
      description: "Exam accommodations • Note-taking support • Accessible campus navigation • Personalized academic plans",
      buttonText: "FREE CONSULTATION",
    },
    {
      image: "/images/banner2.avif  ", // Disabled student using assistive tech in library
      title: "WE ARE REGISTERED NDIS PROVIDER",
      subtitle: "ACADEMIC ACCESSIBILITY",
      highlight: "MADE SIMPLE",
      description: "Real-time request tracking • Quick approvals • Support for exams, lectures & assignments",
      buttonText: "SUBMIT REQUEST NOW",
    },
    {
      image: "/images/banner1.avif", // Student with disability participating in group study on campus
      title: "WE ARE REGISTERED NDIS PROVIDER",
      subtitle: "FULL CAMPUS INCLUSION",
      highlight: "STARTS HERE",
      description: "Transportation • Interpreters • Mental health support • 24/7 student assistance",
      buttonText: "GET SUPPORT TODAY",
    }
  ];

  // Auto-slide every 5 seconds
  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentSlide((prev) => (prev === slides.length - 1 ? 0 : prev + 1));
    }, 5000);
    return () => clearInterval(interval);
  }, [slides.length]);

  const goToSlide = (index) => setCurrentSlide(index);
  const nextSlide = () => setCurrentSlide((prev) => (prev === slides.length - 1 ? 0 : prev + 1));
  const prevSlide = () => setCurrentSlide((prev) => (prev === 0 ? slides.length - 1 : prev - 1));

  return (
    <div className="relative h-screen max-h-[700px] overflow-hidden">
      {/* Slides */}
      {slides.map((slide, index) => (
        <div
          key={index}
          className={`absolute inset-0 transition-all duration-1000 ease-in-out ${
            index === currentSlide ? 'opacity-100 z-10' : 'opacity-0 z-0'
          }`}
        >
          {/* Background Image - Disability student in university */}
          <Image
            src={slide.image}
            alt={slide.highlight}
            fill
            priority={index === 0}
            className="object-cover"
            sizes="100vw"
          />

          {/* Palette overlay (consistent with your color palette) */}
          <div className="absolute inset-0 bg-gradient-to-r from-[#41654F]/70 via-[#41654F]/50 to-transparent"></div>

          {/* Content Area - Matches the exact design & layout of hero.jpg but with university theme */}
          <div className="relative z-20 max-w-7xl mx-auto px-6 h-full flex items-center">
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-12 items-center w-full">
              
              {/* Left Text + Curve (exact visual from your hero.jpg) */}
              <div className="relative">
                {/* Green curve - exact match to your image */}
                <svg 
                  className="absolute -left-10 -top-12 w-[420px] h-[420px] lg:w-[520px] lg:h-[520px] text-[#9DCCB0] z-0"
                  viewBox="0 0 600 600" 
                  fill="none" 
                  xmlns="http://www.w3.org/2000/svg"
                >
                  <path 
                    d="M0 600 Q150 400 300 350 Q450 300 600 600 Z" 
                    fill="#9DCCB0" 
                    opacity="0.95"
                  />
                </svg>

                <div className="relative z-10 max-w-lg">
                  {/* NDIS Badge */}
                  <div className="inline-flex items-center gap-3 bg-white/90 backdrop-blur-md px-6 py-3 rounded-3xl text-[#41654F] text-sm font-semibold mb-6 shadow-inner">
                    <span className="text-[#9DCCB0] text-xl">●</span>
                    {slide.title}
                  </div>

                  {/* Main Title - using your palette */}
                  <h1 className="text-5xl md:text-6xl lg:text-7xl font-bold leading-none text-white">
                    {slide.subtitle}
                    <span className="block text-[#9DCCB0] mt-2">{slide.highlight}</span>
                  </h1>

                  {/* Description */}
                  <p className="mt-8 text-xl text-[#F3E3CD] max-w-md">
                    {slide.description}
                  </p>

                  {/* Button - exact style from your hero.jpg using palette */}
                  <Link href="/request">
                    <button className="mt-10 group flex items-center gap-3 bg-[#41654F] hover:bg-[#9DCCB0] hover:text-[#41654F] text-white px-10 py-5 rounded-3xl font-semibold text-lg transition-all duration-300 shadow-xl hover:shadow-2xl">
                      {slide.buttonText}
                      <ArrowRight className="w-6 h-6 group-active:rotate-45 transition-transform" />
                    </button>
                  </Link>
                </div>
              </div>

              {/* Right side is the image itself (already full background) */}
            </div>
          </div>
        </div>
      ))}

      {/* Slide Dots - styled with your palette */}
      <div className="absolute bottom-10 left-1/2 -translate-x-1/2 z-30 flex gap-4">
        {slides.map((_, index) => (
          <button
            key={index}
            onClick={() => goToSlide(index)}
            className={`w-4 h-4 rounded-full transition-all duration-300 border-2 border-white ${
              index === currentSlide 
                ? 'bg-[#9DCCB0] scale-125' 
                : 'bg-transparent hover:bg-white/50'
            }`}
            aria-label={`Go to slide ${index + 1}`}
          />
        ))}
      </div>

      {/* Navigation Arrows - palette styled */}
      <button
        onClick={prevSlide}
        className="absolute left-6 top-1/2 -translate-y-1/2 z-30 w-12 h-12 bg-white/10 hover:bg-white/20 backdrop-blur-md rounded-2xl flex items-center justify-center text-white transition-all"
        aria-label="Previous"
      >
        <svg xmlns="http://www.w3.org/2000/svg" className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 19l-7-7 7-7" />
        </svg>
      </button>

      <button
        onClick={nextSlide}
        className="absolute right-6 top-1/2 -translate-y-1/2 z-30 w-12 h-12 bg-white/10 hover:bg-white/20 backdrop-blur-md rounded-2xl flex items-center justify-center text-white transition-all"
        aria-label="Next"
      >
        <svg xmlns="http://www.w3.org/2000/svg" className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M9 5l7 7-7 7" />
        </svg>
      </button>
    </div>
  );
}